//! Raw FFI bindings for libswupdate's public IPC surface.
//!
//! Generated by `bindgen` from the headers in `vendor/swupdate/`
//! (LGPL-2.1-or-later). Dynamic-linked against `libswupdate.so` so a
//! consumer's binary may use any compatible permissive license.
//!
//! Higher-level safe wrappers live in the consumer crate
//! (`bridgething::ota::swupdate_ffi`); this crate is intentionally
//! limited to the raw bindings.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
